def check_privacy(records, qi, sensitive, k, l):
    groups = {}
    for r in records:
        key = tuple(r[a] for a in qi)  # 준식별자 값 조합
        groups.setdefault(key, []).append(r)
    # 동질집합 = groups의 각 값
    k_ok = all(len(g) >= k for g in groups.values())
    l_ok = all(len({r[sensitive] for r in g}) >= l
               for g in groups.values())
    return k_ok, l_ok  # k-익명성, l-다양성 여부
